   for(String key:List.of("HEADCOUNT","WORK_HOURS","ENERGY_KWH","WATER_TON","ROOM_NIGHTS")){var metric=measurement(metrics,key);Object val=metric==null?null:metric.get("value");String label=switch(key){case "HEADCOUNT"->"已确认月均人数";case "WORK_HOURS"->"已确认实际工时（人工来源，非企微自动考勤）";case "ENERGY_KWH"->"已确认用电量";case "WATER_TON"->"已确认用水量";default->"已确认售出间夜";};facts.add(fact(hotelId+":"+key,hotelId,label,val,metric!=null,metric==null?"未导入或确认该项真实经营来源":metric.get("source_reference").toString(),switch(key){case "HEADCOUNT"->"PERSON";case "WORK_HOURS"->"HOUR";case "ENERGY_KWH"->"KWH";case "WATER_TON"->"TON";default->"ROOM_NIGHT";},"METRIC:"+(metric==null?"MISSING":metric.get("id")+":"+metric.get("version"))));}
   addIntensity(facts,hotelId,metrics,"ENERGY_KWH","ROOM_NIGHTS","ENERGY_PER_ROOM_NIGHT","实测每间夜电耗","KWH/ROOM_NIGHT",null,true);
