     var usage=jdbc.queryForMap("select coalesce(sum(u.amount) filter(where u.state='COMMITTED'),0) committed,coalesce(sum(u.amount) filter(where u.state='INFLIGHT'),0) inflight,coalesce(sum(u.amount) filter(where u.state='ACTUAL'),0) actual,coalesce(sum(u.amount) filter(where u.state='RELEASED'),0) released,max(u.updated_at) updated_at from fc_budget_usage u join fc_policy old on old.tenant_id=u.tenant_id and old.id=u.policy_id where u.tenant_id=:tenant and old.hotel_id=:hotel and old.kind='BUDGET' and old.code=:code and old.spec->>'month'=:requested"+(projectColumn?" and u.project_key=:projectKey":""),control.addValue("projectKey",projectKey));line.putAll(usage);line.put("budget_kind",spec.get("budgetKind"));budget.add(line);
