 private Map<String,Object> fact(String id,UUID hotel,String label,Object value,boolean complete,String reason,String unit,String source){var r=new LinkedHashMap<String,Object>();r.put("id",id);r.put("hotelId",hotel);r.put("label",label);r.put("value",value);r.put("complete",complete);r.put("explanation",reason);r.put("unit",unit);r.put("sourceReportVersion",source);return r;}
